from fastapi import APIRouter, Depends

from app.api.dependencies import require_role
from app.models.user import Role, User

router = APIRouter(prefix="/dev/access", tags=["Development RBAC checks"])


@router.get("/admin")
def admin(user: User = Depends(require_role(Role.INSPECTOR))):
    return {"allowed": True, "role": user.role, "capability": "administration"}


@router.get("/inspection")
def inspection(user: User = Depends(require_role(Role.INSPECTOR))):
    return {"allowed": True, "role": user.role, "capability": "inspection_creation"}


@router.get("/monitoring")
def monitoring(user: User = Depends(require_role(Role.INSPECTOR))):
    return {"allowed": True, "role": user.role, "capability": "monitoring"}

import hashlib
import json
from uuid import uuid4
from fastapi import HTTPException
from sqlalchemy import select
from sqlalchemy.exc import IntegrityError
from app.models.context import ContextResolutionRun, InspectionContext, ContextFact, RuleInputSnapshot
from app.models.extraction import ExtractionRun
from app.models.user import Role, utc_now
from app.ocr.service import check_inspection_access
from app.extraction.service import ExtractionService
from app.extraction.schemas import candidate_response
from app.context.resolver import resolve
from app.context.facts import safe

def canonical(value):
    return json.dumps(value,sort_keys=True,separators=(",",":"),ensure_ascii=True,allow_nan=False)

def digest(value):
    return hashlib.sha256(canonical(value).encode()).hexdigest()

class ContextService:
    def __init__(self,db,settings):
        self.db,self.settings=db,settings

    def access(self,inspection_id,user,write=False):
        inspection=check_inspection_access(self.db,inspection_id,user)
        if user.role==Role.INSPECTOR and inspection.created_by_user_id!=user.id:
            raise HTTPException(404,"Inspection not found")
        if write and user.role != Role.INSPECTOR:
            raise HTTPException(403,"Not authorized to resolve context")
        return inspection

    def inputs(self,inspection,update=None):
        previous=self.db.scalar(select(ContextResolutionRun).where(ContextResolutionRun.inspection_id==inspection.id)
            .order_by(ContextResolutionRun.selected_at.desc(),ContextResolutionRun.id.desc()))
        inspector_input=dict(previous.inspector_input) if previous else {}
        if update is not None:
            # null removes an explicit override; omissions retain prior input.
            for key,value in update.items():
                if value is None:
                    inspector_input.pop(key,None)
                else:
                    inspector_input[key]=value
        extraction=ExtractionService(self.db,self.settings)
        latest,images,extraction_fingerprint=extraction.snapshot(inspection)
        extraction_run=self.db.scalar(select(ExtractionRun).where(
            ExtractionRun.inspection_id==inspection.id,
            ExtractionRun.version==self.settings.extraction_pipeline_version,
            ExtractionRun.input_fingerprint==extraction_fingerprint))
        candidates=[candidate_response(c).model_dump(mode="json") for c in extraction_run.candidates] if extraction_run else []
        # Bound before copying source evidence into a new snapshot.
        if len(candidates)>1000 or len(canonical(candidates))>2_000_000:
            raise HTTPException(422,"Declaration evidence exceeds context snapshot limits")
        bundle={"inspection_id":inspection.id,"context_version":self.settings.context_pipeline_version,
            "extraction_version":self.settings.extraction_pipeline_version,
            "metadata":{"product_category":safe(inspection.category),"package_type":safe(inspection.package_type),
                        "import_status":inspection.import_status.value if inspection.import_status else "UNKNOWN"},
            "inspector_input":inspector_input,
            "extraction_run_id":extraction_run.id if extraction_run else None,
            "extraction_status":extraction_run.status.value if extraction_run else None,
            "candidates":sorted(candidates,key=lambda c:c["id"]),
            "images":[{"id":i.id,"panel":i.panel_type.value,"sha256":i.sha256,
                       "quality":i.processing_result.quality_status.value if i.processing_result else (i.quality_status or "ACCEPTABLE"),
                       "processing_version":i.processing_result.processing_version if i.processing_result else None,
                       "derived_sha256":i.processing_result.derived_sha256 if i.processing_result else None}
                      for i in sorted(images.values(),key=lambda i:i.id)],
            "ocr":[{"id":r.id,"image_id":r.inspection_image_id,"status":r.status.value,
                    "block_count":r.block_count,"confidence":r.average_confidence}
                   for r in sorted(latest.values(),key=lambda r:r.id)]}
        return bundle,digest(bundle)

    def current(self,inspection_id,user):
        inspection=self.access(inspection_id,user)
        bundle,fingerprint=self.inputs(inspection)
        return self.db.scalar(select(ContextResolutionRun).where(
            ContextResolutionRun.inspection_id==inspection_id,ContextResolutionRun.version==self.settings.context_pipeline_version,
            ContextResolutionRun.input_fingerprint==fingerprint))

    def run(self,inspection_id,user,update=None):
        inspection=self.access(inspection_id,user,write=True)
        bundle,fingerprint=self.inputs(inspection,update)
        cached=self.db.scalar(select(ContextResolutionRun).where(ContextResolutionRun.inspection_id==inspection_id,
            ContextResolutionRun.version==self.settings.context_pipeline_version,ContextResolutionRun.input_fingerprint==fingerprint))
        if cached:
            if update is not None:
                cached.selected_at=utc_now()
                self.db.commit()
            return self.context(cached)
        started_at=utc_now()
        result=resolve(bundle,fingerprint)
        run=ContextResolutionRun(id=str(uuid4()),inspection_id=inspection_id,version=self.settings.context_pipeline_version,
            input_fingerprint=fingerprint,inspector_input=bundle["inspector_input"],started_at=started_at,
            status="SUCCESS" if result["evidence"]["state"]=="SUFFICIENT_FOR_RULE_EVALUATION" else "PARTIAL",
            facts_created=len(result["facts"]),conflicts_detected=len(result["conflicts"]),completed_at=utc_now())
        context=InspectionContext(inspection_id=inspection_id,run_id=run.id,context_version=run.version,
            resolved=result["resolved"],resolution_status=result["resolution_status"],evidence=result["evidence"],conflicts=result["conflicts"])
        content={"schema_version":"1","inspection_id":inspection_id,"context_version":run.version,
            "context_run_id":run.id,"input_fingerprint":fingerprint,"resolved":result["resolved"],
            "context_keys":result["context_keys"],"evidence":result["evidence"],"conflicts":result["conflicts"],
            "facts":result["facts"],"declarations":bundle["candidates"],"source_inputs":bundle,
            "applicability_preview":result["applicability"],
            "limitations":["Context and applicability preparation are not legal evaluation.",
                "Candidate detection does not establish declaration presence or absence.",
                "No verified legal conditions are executed."]}
        if len(canonical(content))>5_000_000:
            raise HTTPException(422,"Context snapshot exceeds 5 MB limit")
        snapshot=RuleInputSnapshot(inspection_id=inspection_id,run_id=run.id,content=content,content_sha256=digest(content))
        try:
            self.db.add(run)
            self.db.flush()
            self.db.add(context)
            self.db.add_all([ContextFact(**f,inspection_id=inspection_id,run_id=run.id) for f in result["facts"]])
            self.db.add(snapshot)
            self.db.commit()
        except IntegrityError:
            self.db.rollback()
            cached=self.current(inspection_id,user)
            if cached:
                return self.context(cached)
            raise
        except Exception:
            self.db.rollback()
            raise
        return self.context(run)

    def context(self,run):
        if not run:
            return {"run":None,"message":"Context has not been resolved for the current evidence and settings."}
        context=self.db.scalar(select(InspectionContext).where(InspectionContext.run_id==run.id))
        return {"run":{"id":run.id,"version":run.version,"status":run.status,"facts_created":run.facts_created,
                       "conflicts_detected":run.conflicts_detected,"started_at":run.started_at,"completed_at":run.completed_at},
                "inspection_id":run.inspection_id,"resolved":context.resolved,"resolution_status":context.resolution_status,
                "evidence":context.evidence,"conflicts":context.conflicts,"inspector_input":run.inspector_input}

    def snapshot(self,inspection_id,user,snapshot_id=None):
        self.access(inspection_id,user)
        if snapshot_id:
            snapshot=self.db.scalar(select(RuleInputSnapshot).where(RuleInputSnapshot.id==snapshot_id,
                                                                  RuleInputSnapshot.inspection_id==inspection_id))
        else:
            run=self.current(inspection_id,user)
            snapshot=self.db.scalar(select(RuleInputSnapshot).where(RuleInputSnapshot.run_id==run.id)) if run else None
        if snapshot is None:
            raise HTTPException(404,"Rule input snapshot not found; resolve current context first")
        if digest(snapshot.content)!=snapshot.content_sha256:
            raise HTTPException(409,"Snapshot integrity check failed")
        return {"id":snapshot.id,"content_sha256":snapshot.content_sha256,"created_at":snapshot.created_at,"content":snapshot.content}

import { useEffect, useState } from 'react'
import { api } from '../api/client'

const fields = [
  ['package_type', 'Package type', ['PACKET','BOX','BOTTLE','JAR','CAN','POUCH','TUBE','CARTON','OTHER','UNKNOWN']],
  ['product_category', 'Product category', ['FOOD','COSMETIC','HOUSEHOLD','PERSONAL_CARE','ELECTRONICS','OTHER','UNKNOWN']],
  ['import_status', 'Import status', ['DOMESTIC','IMPORTED','UNKNOWN']],
  ['quantity_kind', 'Quantity kind', ['WEIGHT','VOLUME','COUNT','LENGTH','AREA','UNKNOWN']],
]
const label = value => String(value ?? 'Unknown').replaceAll('_', ' ')
const display = value => value === null ? 'Unknown' : value === false ? 'No candidate detected' : value === true ? 'Yes' : label(value)

export default function ContextApplicability({ inspection, user, refreshKey, ocrRefresh }) {
  const [context, setContext] = useState(null)
  const [facts, setFacts] = useState([])
  const [preview, setPreview] = useState([])
  const [input, setInput] = useState({})
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [debug, setDebug] = useState(null)
  const base = '/inspections/' + inspection.id
  const canResolve = user?.role === 'INSPECTOR' || (user?.role === 'INSPECTOR' && user.id === inspection.created_by_user_id)

  async function load(signal) {
    const response = await api.get(base + '/context', { signal })
    if (signal?.aborted) return
    setContext(response.data); setDebug(null)
    if (response.data.run) {
      const [f, p] = await Promise.all([api.get(base + '/context/facts', { signal }), api.get(base + '/applicability-preview', { signal })])
      if (!signal?.aborted) { setFacts(f.data); setPreview(p.data.items) }
    } else { setFacts([]); setPreview([]) }
  }
  useEffect(() => {
    const controller = new AbortController()
    setError('')
    load(controller.signal).catch(e => { if (!controller.signal.aborted) setError(e.response?.data?.detail || 'Unable to load context.') })
    return () => controller.abort()
  }, [inspection.id, inspection.updated_at, refreshKey, ocrRefresh])

  async function resolve(clear = false) {
    setBusy(true); setError('')
    const values = clear ? Object.fromEntries([...fields.map(f => f[0]), 'country_of_origin'].map(k => [k, null])) :
      Object.fromEntries(Object.entries(input).filter(([, v]) => v !== ''))
    try {
      await api.post(base + '/resolve-context', { inspector_input: values }, { timeout: 30000 })
      setInput({})
      await load()
    } catch (e) {
      setError(typeof e.response?.data?.detail === 'string' ? e.response.data.detail : 'Unable to resolve context. Check the entered values.')
    } finally { setBusy(false) }
  }
  async function showDebug() {
    try { setDebug((await api.get(base + '/rule-input')).data) }
    catch { setError('Unable to load the current rule-input snapshot.') }
  }

  return <section className="panel my-6">
    <h2>Context &amp; Applicability</h2>
    <p className="text-sm text-stone-600 my-3">Context and candidate detection prepare an inspection for later evaluation. This preview does not determine legal compliance.</p>
    {error && <p role="alert" className="text-rose-800">{typeof error === 'string' ? error : 'Unable to load context.'}</p>}
    {canResolve && <details className="my-4 border border-stone-200 p-3 rounded">
      <summary className="cursor-pointer font-semibold">Inspector context input</summary>
      <p className="text-xs text-stone-500 my-2">Optional inputs are saved separately from inspection metadata. Competing evidence remains visible.</p>
      <div className="grid md:grid-cols-2 gap-3">
        {fields.map(([key, name, options]) => <label key={key} className="text-sm">{name}
          <select value={input[key] || ''} onChange={e => setInput({ ...input, [key]: e.target.value })} className="block w-full border p-2 rounded">
            <option value="">Keep saved input / metadata</option>
            {options.map(v => <option key={v} value={v}>{label(v)}</option>)}
          </select>
        </label>)}
        <label className="text-sm">Country of origin
          <input maxLength={100} value={input.country_of_origin || ''} onChange={e => setInput({ ...input, country_of_origin: e.target.value })} className="block w-full border p-2 rounded" />
        </label>
      </div>
      {context?.inspector_input && <p className="text-xs text-stone-600 mt-3">Saved inputs: {Object.entries(context.inspector_input).map(([k,v]) => label(k) + ': ' + label(v)).join(' · ') || 'None'}</p>}
      <button className="mt-3" disabled={busy} onClick={() => resolve(true)}>Clear saved inputs and resolve</button>
    </details>}
    {canResolve && <button disabled={busy} onClick={() => resolve()}>{busy ? 'Resolving…' : 'Resolve context'}</button>}
    {!context?.run && <p className="text-stone-500 my-3">No current context snapshot. Resolve context after evidence, extraction, or metadata changes. Resolution can begin before OCR; limitations will be shown.</p>}
    {context?.run && <>
      <h3 className="font-semibold mt-5 mb-3">Product and package context</h3>
      <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3">
        {['PRODUCT_CATEGORY','PACKAGE_TYPE','IMPORT_STATUS','COUNTRY_OF_ORIGIN','QUANTITY_KIND'].map(key => {
          const fact = context.resolved[key]
          return <article key={key} className={'p-3 border rounded ' + (['CONFLICTING','REVIEW_REQUIRED'].includes(fact.state) ? 'bg-amber-50 border-amber-300' : 'border-stone-200')}>
            <h4 className="text-xs text-stone-500">{label(key)}</h4>
            <p className="font-semibold">{display(fact.value)}</p>
            <p className="text-xs">{label(fact.state)} · {label(fact.source_type)}</p>
            {fact.confidence !== null && <p className="text-xs">Source confidence: {Math.round(fact.confidence * 100)}%</p>}
          </article>
        })}
      </div>
      <h3 className="font-semibold mt-5">Evidence sufficiency</h3>
      <p className="my-2">{label(context.evidence.state)}</p>
      {context.evidence.reasons.map(r => <p key={r} className="text-sm text-stone-600">{r}</p>)}
      {context.conflicts.length > 0 && <div role="status" className="my-4 p-3 bg-amber-50 border border-amber-300 rounded">
        <h3 className="font-semibold">Conflicts / review required</h3>
        {context.conflicts.map(c => <div key={c.fact_type} className="mt-3">
          <strong>{label(c.fact_type)}</strong>
          {c.sources.map(s => <p key={s.fact_id} className="text-sm whitespace-pre-wrap">{label(s.source_type)}: {display(s.value)} — {s.raw}</p>)}
          <p className="text-xs">{c.reason}</p>
        </div>)}
      </div>}
      <details className="my-4">
        <summary className="cursor-pointer font-semibold">Context facts and sources ({facts.length})</summary>
        <div className="overflow-x-auto"><table className="w-full text-left text-xs mt-3">
          <thead><tr>{['Fact','Value','State','Source','Evidence / explanation'].map(h => <th key={h} className="p-2 border-b">{h}</th>)}</tr></thead>
          <tbody>{facts.map(f => <tr key={f.id}>
            <td className="p-2">{label(f.fact_type)}</td>
            <td className="p-2">{display(f.value.normalized)}</td>
            <td className="p-2">{label(f.resolution_state)}</td>
            <td className="p-2">{label(f.source_type)}<small className="block break-all">{f.source_reference_id}</small></td>
            <td className="p-2 whitespace-pre-wrap break-words">{String(f.value.raw ?? 'Unknown')}<small className="block">{f.explanation}</small></td>
          </tr>)}</tbody>
        </table></div>
      </details>
      <h3 className="font-semibold mt-4">Applicability preview</h3>
      <p className="text-sm text-amber-800 my-2">Legal verification pending. These preparation hints cannot execute rules.</p>
      <div className="grid md:grid-cols-2 gap-3">{preview.map(p => <article key={p.rule_key} className="border border-stone-200 rounded p-3">
        <h4 className="font-medium text-sm">{label(p.rule_key.replace('DECLARATION_', ''))} declaration</h4>
        <p className="text-sm">{label(p.state)}</p><p className="text-xs text-stone-500">{p.reason}</p>
      </article>)}</div>
      {user?.role === 'INSPECTOR' && <details className="mt-4"><summary onClick={() => { if (!debug) showDebug() }} className="cursor-pointer">Rule input snapshot (admin)</summary>
        {debug && <pre className="text-xs overflow-auto max-h-96 whitespace-pre-wrap break-words">{JSON.stringify(debug, null, 2)}</pre>}
      </details>}
    </>}
  </section>
}

import { useEffect, useState } from 'react'
import { api } from '../api/client'
import OCRBoundingBoxCanvas from './OCRBoundingBoxCanvas'

export default function ExtractedDeclarations({ inspection, user, refreshKey, onExtractionComplete }) {
  const [candidates, setCandidates] = useState([])
  const [summary, setSummary] = useState(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [selected, setSelected] = useState(null)
  const [selectedBlock, setSelectedBlock] = useState(null)
  const base = '/inspections/' + inspection.id
  const canRun = user?.role === 'INSPECTOR' || (user?.role === 'INSPECTOR' && user.id === inspection.created_by_user_id)

  async function load(signal) {
    const [list, report] = await Promise.all([
      api.get(base + '/declarations?limit=1000', { signal }),
      api.get(base + '/extraction-summary', { signal }),
    ])
    if (!signal?.aborted) {
      setCandidates(list.data); setSummary(report.data); setSelected(null)
    }
  }
  useEffect(() => {
    const controller = new AbortController()
    setError('')
    load(controller.signal).catch(e => { if (!controller.signal.aborted) setError(e.response?.data?.detail || 'Unable to load declarations.') })
    return () => controller.abort()
  }, [inspection.id, refreshKey])

  async function run() {
    setBusy(true); setError('')
    try {
      await api.post(base + '/extract-declarations', null, { timeout: 30000 })
      await load()
      onExtractionComplete?.()
    } catch (e) {
      setError(typeof e.response?.data?.detail === 'string' ? e.response.data.detail : 'Unable to extract declarations.')
    } finally { setBusy(false) }
  }

  return <section className="panel my-6">
    <div className="flex justify-between gap-4 items-center">
      <h2>Extracted Declarations</h2>
      {canRun && <button onClick={run} disabled={busy}>{busy ? 'Extracting…' : 'Extract declarations'}</button>}
    </div>
    <p className="text-sm text-stone-600 my-3">Machine-generated candidates for inspector review. Extraction does not establish legal compliance. A missing candidate does not prove a declaration is absent.</p>
    {error && <p role="alert" className="text-rose-800 my-3">{error}</p>}
    {summary?.run && <p className="text-xs text-stone-600 mb-3">
      {summary.candidate_count} candidates · {summary.needs_review_count} need review · Extraction version {summary.run.version}
    </p>}
    {summary?.run?.warnings?.map(w => <p key={w} className="text-amber-800 text-sm">{w}</p>)}
    {summary?.conflicting_types?.length > 0 && <div role="status" className="bg-amber-50 border border-amber-300 p-3 my-3">
      Review required: conflicting candidates for {summary.conflicting_types.map(t => t.replaceAll('_', ' ')).join(', ')}. No primary candidate has been chosen for these types.
    </div>}
    {!candidates.length && <p className="text-stone-500 my-4">{summary?.run ? 'No supported declarations were detected in the current OCR evidence.' : 'Run OCR, then extract declarations. Updated OCR evidence requires a new extraction.'}</p>}
    <div className="overflow-x-auto">
      {candidates.length > 0 && <table className="w-full text-left text-sm">
        <thead><tr>{['Declaration', 'Value', 'Confidence', 'Panel / Image', 'Method', 'Review', 'Evidence'].map(h => <th key={h} className="p-2 border-b">{h}</th>)}</tr></thead>
        <tbody>{candidates.map(c => <tr key={c.id} className={c.needs_review ? 'bg-amber-50' : ''}>
          <td className="p-2">{c.declaration_type.replaceAll('_', ' ')}{c.is_primary && <small className="block text-stone-500">Primary candidate</small>}</td>
          <td className="p-2 whitespace-pre-wrap break-words">{c.declaration_type === 'MRP' ? '₹' : ''}{c.normalized_value}</td>
          <td className="p-2">{Math.round(c.confidence_score * 100)}%</td>
          <td className="p-2">{c.panel_type}<small className="block">{inspection.images?.find(i => i.id === c.source_image_id)?.original_filename || c.source_image_id}</small></td>
          <td className="p-2">{c.extraction_method.replaceAll('_', ' ')}</td>
          <td className="p-2">{c.needs_review ? 'Review required' : 'Auto extracted'}<small className="block">{c.review_reasons.join('; ')}</small></td>
          <td className="p-2"><button onClick={() => { setSelected(c); setSelectedBlock(c.sources[0]?.ocr_block_id) }}>View evidence</button></td>
        </tr>)}</tbody>
      </table>}
    </div>
    {selected && <div className="mt-5 border border-stone-300 rounded p-4">
      <div className="flex justify-between"><h3>Source evidence · {selected.declaration_type.replaceAll('_', ' ')}</h3><button onClick={() => setSelected(null)}>Close evidence</button></div>
      <p className="text-xs text-stone-500 my-2">OCR run: {selected.source_ocr_run_id}</p>
      <OCRBoundingBoxCanvas
        key={selected.id}
        imageUrl={base + '/images/' + selected.source_image_id + (selected.source_image_variant === 'processed' ? '/processed' : '/content')}
        altText="Declaration source evidence"
        blocks={selected.sources.map(s => ({ ...s, id: s.ocr_block_id, confidence_tier: 'REVIEW', reading_order: s.sequence_order }))}
        selectedBlockId={selectedBlock}
        onSelectBlock={b => setSelectedBlock(typeof b === 'string' ? b : b.id)}
        onHoverBlock={() => {}}
      />
      <h4 className="mt-3 font-semibold">Raw OCR text</h4>
      {selected.sources.map(s => <button className="block text-left whitespace-pre-wrap break-words my-2" key={s.ocr_block_id} onClick={() => setSelectedBlock(s.ocr_block_id)}>{s.sequence_order + 1}. {s.raw_text}</button>)}
      <p className="text-xs text-stone-600">Confidence contributions: {Object.entries(selected.confidence_factors).map(([k, v]) => k + ' ' + Math.round(v * 100) + '%').join(' · ')}</p>
    </div>}
  </section>
}

import React, { useState, useEffect } from 'react'
import { api } from '../api/client'

export default function HumanReviewWorkspace({ inspection, user, refreshKey, onReviewUpdated }) {
  const [review, setReview] = useState(null)
  const [auditEvents, setAuditEvents] = useState([])
  const [loading, setLoading] = useState(false)
  const [loadingAudit, setLoadingAudit] = useState(false)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState(null)
  const [successMessage, setSuccessMessage] = useState(null)

  // Rule Decisions editing state
  const [editingRuleKey, setEditingRuleKey] = useState(null)
  const [overrideVerdict, setOverrideVerdict] = useState('')
  const [overrideReason, setOverrideReason] = useState('')
  const [reviewerNotes, setReviewerNotes] = useState('')

  // Finalize / Reopen state
  const [showFinalizeModal, setShowFinalizeModal] = useState(false)
  const [finalComplianceStatus, setFinalComplianceStatus] = useState('COMPLIANT')
  const [summaryNotes, setSummaryNotes] = useState('')
  const [showReopenModal, setShowReopenModal] = useState(false)
  const [reopenReason, setReopenReason] = useState('')

  // Declaration Correction state
  const [showDeclModal, setShowDeclModal] = useState(false)
  const [selectedDeclType, setSelectedDeclType] = useState('MRP')
  const [declRawValue, setDeclRawValue] = useState('')
  const [declCorrectedValue, setDeclCorrectedValue] = useState('')
  const [declAction, setDeclAction] = useState('CORRECTED')
  const [declReason, setDeclReason] = useState('')

  const fetchReview = async () => {
    if (!inspection?.id) return
    setLoading(true)
    setError(null)
    try {
      const res = await api.get(`/inspections/${inspection.id}/review`)
      setReview(res.data)
    } catch (err) {
      if (err.response?.status !== 404) {
        setError(err.response?.data?.detail || 'Failed to load human review record')
      }
    } finally {
      setLoading(false)
    }
  }

  const fetchAudit = async () => {
    if (!inspection?.id) return
    setLoadingAudit(true)
    try {
      const res = await api.get(`/inspections/${inspection.id}/audit-trail`)
      setAuditEvents(res.data || [])
    } catch {
      // Non-fatal
    } finally {
      setLoadingAudit(false)
    }
  }

  useEffect(() => {
    fetchReview()
    fetchAudit()
  }, [inspection?.id, refreshKey])

  const isFinalized = review?.status === 'FINALIZED'
  const isSupervisor = user?.role === 'SUPERVISOR'
  const isAdmin = user?.role === 'INSPECTOR'
  const canEdit = !isFinalized && !isSupervisor

  const handleSaveRuleDecision = async (ruleKey, ruleId, currentMachineVerdict) => {
    if (!overrideVerdict) return
    const isOverriding = overrideVerdict !== currentMachineVerdict
    if (isOverriding && (!overrideReason || overrideReason.trim().length < 5)) {
      setError('An override reason of at least 5 characters is mandatory when changing a machine verdict.')
      return
    }

    setSaving(true)
    setError(null)
    try {
      await api.post(`/inspections/${inspection.id}/review/rule-decisions`, {
        rule_id: ruleId || ruleKey,
        rule_key: ruleKey,
        final_verdict: overrideVerdict,
        override_reason: isOverriding ? overrideReason.trim() : null,
        reviewer_notes: reviewerNotes.trim() || null
      })
      setSuccessMessage(`Decision for ${ruleKey} recorded successfully.`)
      setEditingRuleKey(null)
      setOverrideReason('')
      setReviewerNotes('')
      await fetchReview()
      await fetchAudit()
      if (onReviewUpdated) onReviewUpdated()
    } catch (err) {
      setError(err.response?.data?.detail || 'Failed to record rule decision')
    } finally {
      setSaving(false)
    }
  }

  const handleAddDeclarationCorrection = async (e) => {
    e.preventDefault()
    if (!declCorrectedValue.trim() || !declReason.trim()) {
      setError('Corrected value and justification reason are required.')
      return
    }

    setSaving(true)
    setError(null)
    try {
      await api.post(`/inspections/${inspection.id}/review/declaration-corrections`, {
        declaration_type: selectedDeclType,
        original_raw_value: declRawValue.trim() || null,
        original_normalized_value: null,
        corrected_value: declCorrectedValue.trim(),
        action: declAction,
        correction_reason: declReason.trim()
      })
      setSuccessMessage('Declaration correction saved.')
      setShowDeclModal(false)
      setDeclCorrectedValue('')
      setDeclRawValue('')
      setDeclReason('')
      await fetchReview()
      await fetchAudit()
      if (onReviewUpdated) onReviewUpdated()
    } catch (err) {
      setError(err.response?.data?.detail || 'Failed to record declaration correction')
    } finally {
      setSaving(false)
    }
  }

  const handleFinalize = async () => {
    setSaving(true)
    setError(null)
    try {
      const res = await api.post(`/inspections/${inspection.id}/review/finalize`, {
        final_compliance_status: finalComplianceStatus,
        summary_notes: summaryNotes.trim() || null
      })
      setReview(res.data)
      setShowFinalizeModal(false)
      setSuccessMessage('Review finalized and locked. Chain of custody sealed.')
      await fetchAudit()
      if (onReviewUpdated) onReviewUpdated()
    } catch (err) {
      setError(err.response?.data?.detail || 'Failed to finalize review')
    } finally {
      setSaving(false)
    }
  }

  const handleReopen = async () => {
    if (!reopenReason.trim() || reopenReason.trim().length < 5) {
      setError('A valid justification of at least 5 characters is mandatory to reopen a review.')
      return
    }

    setSaving(true)
    setError(null)
    try {
      const res = await api.post(`/inspections/${inspection.id}/review/reopen`, {
        reopen_reason: reopenReason.trim()
      })
      setReview(res.data)
      setShowReopenModal(false)
      setReopenReason('')
      setSuccessMessage('Inspection review reopened for authorized amendments.')
      await fetchAudit()
      if (onReviewUpdated) onReviewUpdated()
    } catch (err) {
      setError(err.response?.data?.detail || 'Failed to reopen review')
    } finally {
      setSaving(false)
    }
  }

  return (
    <section className="bg-white border border-stone-300 rounded-lg shadow-sm p-6 mb-8">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-4 border-b border-stone-200">
        <div>
          <div className="flex items-center gap-2">
            <span className="text-xs font-bold uppercase tracking-wider text-emerald-900 bg-emerald-100 px-2 py-0.5 rounded">
              Phase 10
            </span>
            <h2 className="text-base font-bold text-stone-900">
              Inspector Review, Overrides & Finalization
            </h2>
          </div>
          <p className="text-xs text-stone-500 mt-1">
            Human verification authority under Legal Metrology Act, 2009. Machine rules propose verdicts; authorized officers confirm or override with immutable justification.
          </p>
        </div>

        {/* Status badges & finalization controls */}
        <div className="flex items-center gap-3">
          {review && (
            <div className="flex items-center gap-2">
              <span className="text-xs text-stone-500">Review Status:</span>
              <span className={`text-xs px-2.5 py-1 rounded-full font-bold border ${
                review.status === 'FINALIZED'
                  ? 'bg-purple-100 text-purple-900 border-purple-300'
                  : review.status === 'REOPENED'
                  ? 'bg-amber-100 text-amber-900 border-amber-300'
                  : 'bg-blue-100 text-blue-900 border-blue-300'
              }`}>
                {review.status}
              </span>
              {review.final_compliance_status && (
                <span className={`text-xs px-2.5 py-1 rounded font-bold border ${
                  review.final_compliance_status === 'COMPLIANT'
                    ? 'bg-emerald-100 text-emerald-800 border-emerald-300'
                    : review.final_compliance_status === 'NON_COMPLIANT'
                    ? 'bg-rose-100 text-rose-800 border-rose-300'
                    : 'bg-amber-100 text-amber-800 border-amber-300'
                }`}>
                  {review.final_compliance_status}
                </span>
              )}
            </div>
          )}

          {canEdit && (
            <button
              type="button"
              onClick={() => setShowFinalizeModal(true)}
              className="px-3.5 py-1.5 text-xs font-bold text-white bg-emerald-900 hover:bg-emerald-800 rounded shadow transition-colors"
            >
              🔒 Finalize Review
            </button>
          )}

          {isFinalized && isAdmin && (
            <button
              type="button"
              onClick={() => setShowReopenModal(true)}
              className="px-3 py-1.5 text-xs font-bold text-amber-900 bg-amber-100 hover:bg-amber-200 border border-amber-300 rounded shadow-sm transition-colors"
            >
              🔓 Reopen Review (Admin)
            </button>
          )}
        </div>
      </div>

      {/* Notifications */}
      {error && (
        <div className="my-4 p-3 bg-rose-50 border-l-4 border-rose-600 text-rose-900 text-xs rounded flex justify-between items-center">
          <span>{error}</span>
          <button type="button" onClick={() => setError(null)} className="font-bold text-rose-950">✕</button>
        </div>
      )}
      {successMessage && (
        <div className="my-4 p-3 bg-emerald-50 border-l-4 border-emerald-600 text-emerald-900 text-xs rounded flex justify-between items-center">
          <span>{successMessage}</span>
          <button type="button" onClick={() => setSuccessMessage(null)} className="font-bold text-emerald-950">✕</button>
        </div>
      )}

      {/* Notice Banner */}
      {isFinalized && (
        <div className="my-4 p-3.5 bg-stone-100 border border-stone-300 rounded text-xs text-stone-700 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="text-stone-900 font-bold">🔒 Sealed Record:</span>
            <span>This inspection review was finalized on {review?.finalized_at ? new Date(review.finalized_at).toLocaleString() : 'N/A'}. All verdicts, corrections, and observations are permanently locked.</span>
          </div>
          {review?.summary_notes && (
            <span className="italic text-stone-600 ml-4 font-mono text-[11px]">Note: "{review.summary_notes}"</span>
          )}
        </div>
      )}

      {/* Grid of Sections */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mt-6">
        {/* Left Column: Recorded Rule Overrides / Decisions */}
        <div className="space-y-4">
          <div className="flex items-center justify-between border-b pb-2">
            <h3 className="text-xs font-bold uppercase tracking-wider text-stone-800">
              Rule Review Decisions ({review?.rule_decisions?.length || 0})
            </h3>
            <span className="text-[11px] text-stone-500">
              {review?.rule_decisions?.filter(d => d.is_overridden).length || 0} overridden
            </span>
          </div>

          {loading ? (
            <div className="p-4 text-center text-xs text-stone-500 animate-pulse">Loading review decisions…</div>
          ) : !review || review.rule_decisions.length === 0 ? (
            <div className="p-6 bg-stone-50 border border-dashed border-stone-300 rounded text-center text-xs text-stone-500">
              No rule decisions recorded yet. Evaluated rules can be reviewed directly in the Rule Compliance section or customized below.
            </div>
          ) : (
            <div className="space-y-3">
              {review.rule_decisions.map((dec) => (
                <div key={dec.id} className="p-3.5 border border-stone-200 rounded-lg bg-stone-50 text-xs space-y-2">
                  <div className="flex items-center justify-between">
                    <span className="font-bold text-stone-900">{dec.rule_key}</span>
                    <div className="flex items-center gap-1.5">
                      <span className="text-[10px] text-stone-500">Machine:</span>
                      <span className="px-1.5 py-0.5 rounded bg-stone-200 text-stone-700 font-mono text-[10px]">
                        {dec.original_verdict}
                      </span>
                      <span className="text-stone-400">➔</span>
                      <span className="text-[10px] text-stone-500">Inspector:</span>
                      <span className={`px-2 py-0.5 rounded font-bold text-[10px] ${
                        dec.final_verdict === 'PASS'
                          ? 'bg-emerald-100 text-emerald-800'
                          : dec.final_verdict === 'FAIL'
                          ? 'bg-rose-100 text-rose-800'
                          : 'bg-amber-100 text-amber-800'
                      }`}>
                        {dec.final_verdict}
                      </span>
                    </div>
                  </div>

                  {dec.is_overridden && (
                    <div className="p-2 bg-amber-50 border-l-2 border-amber-500 rounded text-[11px] text-amber-900">
                      <div className="font-semibold text-amber-950">Mandatory Override Justification:</div>
                      <p className="mt-0.5">{dec.override_reason}</p>
                    </div>
                  )}

                  {dec.reviewer_notes && (
                    <div className="text-[11px] text-stone-600 italic">
                      Notes: {dec.reviewer_notes}
                    </div>
                  )}

                  <div className="text-[10px] text-stone-400 flex justify-between items-center pt-1 border-t border-stone-200">
                    <span>Recorded: {new Date(dec.created_at).toLocaleTimeString()}</span>
                    {dec.is_overridden && (
                      <span className="text-amber-700 font-semibold">⚠️ Overridden by Inspector</span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Right Column: Declaration Corrections & Additions */}
        <div className="space-y-4">
          <div className="flex items-center justify-between border-b pb-2">
            <h3 className="text-xs font-bold uppercase tracking-wider text-stone-800">
              Inspector Declaration Corrections ({review?.declaration_corrections?.length || 0})
            </h3>
            {canEdit && (
              <button
                type="button"
                onClick={() => setShowDeclModal(true)}
                className="px-2.5 py-1 text-[11px] font-bold text-emerald-900 bg-emerald-50 hover:bg-emerald-100 border border-emerald-200 rounded transition-colors"
              >
                + Record Correction
              </button>
            )}
          </div>

          {loading ? (
            <div className="p-4 text-center text-xs text-stone-500 animate-pulse">Loading corrections…</div>
          ) : !review || review.declaration_corrections.length === 0 ? (
            <div className="p-6 bg-stone-50 border border-dashed border-stone-300 rounded text-center text-xs text-stone-500">
              No declaration corrections recorded. AI extractions remain unamended.
            </div>
          ) : (
            <div className="space-y-3">
              {review.declaration_corrections.map((corr) => (
                <div key={corr.id} className="p-3.5 border border-stone-200 rounded-lg bg-stone-50 text-xs space-y-2">
                  <div className="flex items-center justify-between">
                    <span className="font-bold text-stone-900">{corr.declaration_type}</span>
                    <span className="px-2 py-0.5 rounded font-bold text-[10px] bg-blue-100 text-blue-900">
                      {corr.action}
                    </span>
                  </div>

                  {corr.original_raw_value && (
                    <div className="text-[11px] text-stone-500">
                      Original: <span className="line-through">{corr.original_raw_value}</span>
                    </div>
                  )}

                  <div className="text-[11px] text-stone-900 font-semibold">
                    Corrected Value: <span className="font-mono bg-white px-1.5 py-0.5 rounded border">{corr.corrected_value}</span>
                  </div>

                  <div className="p-2 bg-stone-100 rounded text-[11px] text-stone-700">
                    <span className="font-semibold text-stone-900">Reason:</span> {corr.correction_reason}
                  </div>

                  <div className="text-[10px] text-stone-400 text-right pt-1 border-t border-stone-200">
                    {new Date(corr.created_at).toLocaleString()}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Modal: Record Declaration Correction */}
      {showDeclModal && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-lg max-w-lg w-full p-6 shadow-2xl space-y-4">
            <div className="flex justify-between items-center border-b pb-3">
              <h3 className="text-sm font-bold text-stone-900">Record Declaration Correction</h3>
              <button type="button" onClick={() => setShowDeclModal(false)} className="text-stone-400 hover:text-stone-600 font-bold">✕</button>
            </div>

            <form onSubmit={handleAddDeclarationCorrection} className="space-y-3 text-xs">
              <div>
                <label className="block text-stone-700 font-semibold mb-1">Declaration Type</label>
                <select
                  value={selectedDeclType}
                  onChange={(e) => setSelectedDeclType(e.target.value)}
                  className="w-full p-2 border border-stone-300 rounded bg-white"
                >
                  <option value="MRP">MRP (Maximum Retail Price)</option>
                  <option value="NET_QUANTITY">NET_QUANTITY (Net Content)</option>
                  <option value="MONTH_YEAR">MONTH_YEAR (Mfg / Pkd Date)</option>
                  <option value="CONSUMER_CARE_PHONE">CONSUMER_CARE_PHONE</option>
                  <option value="CONSUMER_CARE_EMAIL">CONSUMER_CARE_EMAIL</option>
                  <option value="MANUFACTURER_NAME">MANUFACTURER_NAME</option>
                  <option value="COUNTRY_OF_ORIGIN">COUNTRY_OF_ORIGIN</option>
                  <option value="BARCODE_OR_GTIN">BARCODE_OR_GTIN</option>
                </select>
              </div>

              <div>
                <label className="block text-stone-700 font-semibold mb-1">Original Raw Text (Optional)</label>
                <input
                  type="text"
                  value={declRawValue}
                  onChange={(e) => setDeclRawValue(e.target.value)}
                  placeholder="e.g. MRP 120"
                  className="w-full p-2 border border-stone-300 rounded"
                />
              </div>

              <div>
                <label className="block text-stone-700 font-semibold mb-1">Corrected / Verified Value *</label>
                <input
                  type="text"
                  required
                  value={declCorrectedValue}
                  onChange={(e) => setDeclCorrectedValue(e.target.value)}
                  placeholder="e.g. INR 120.00 (Incl. of all taxes)"
                  className="w-full p-2 border border-stone-300 rounded"
                />
              </div>

              <div>
                <label className="block text-stone-700 font-semibold mb-1">Action Type</label>
                <select
                  value={declAction}
                  onChange={(e) => setDeclAction(e.target.value)}
                  className="w-full p-2 border border-stone-300 rounded bg-white"
                >
                  <option value="CORRECTED">CORRECTED (Amended AI reading)</option>
                  <option value="CONFIRMED">CONFIRMED (Inspector validated)</option>
                  <option value="REJECTED">REJECTED (Invalid / Hallucinated)</option>
                  <option value="MANUALLY_ADDED">MANUALLY_ADDED (Missing from OCR)</option>
                </select>
              </div>

              <div>
                <label className="block text-stone-700 font-semibold mb-1">Justification Reason *</label>
                <textarea
                  required
                  rows={3}
                  value={declReason}
                  onChange={(e) => setDeclReason(e.target.value)}
                  placeholder="State the statutory or physical observation reason for this correction..."
                  className="w-full p-2 border border-stone-300 rounded"
                />
              </div>

              <div className="flex justify-end gap-2 pt-3 border-t">
                <button
                  type="button"
                  onClick={() => setShowDeclModal(false)}
                  className="px-3 py-1.5 bg-stone-100 text-stone-700 rounded hover:bg-stone-200"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={saving}
                  className="px-4 py-1.5 bg-emerald-900 text-white font-bold rounded hover:bg-emerald-800"
                >
                  {saving ? 'Saving…' : 'Save Correction'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal: Finalize Review */}
      {showFinalizeModal && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-lg max-w-md w-full p-6 shadow-2xl space-y-4">
            <div className="flex justify-between items-center border-b pb-3">
              <h3 className="text-sm font-bold text-stone-900">🔒 Finalize Legal Metrology Review</h3>
              <button type="button" onClick={() => setShowFinalizeModal(false)} className="text-stone-400 hover:text-stone-600 font-bold">✕</button>
            </div>

            <div className="p-3 bg-amber-50 border border-amber-200 rounded text-xs text-amber-900">
              <strong>Warning:</strong> Finalizing seals this inspection record into the immutable audit trail. No further edits or overrides will be permitted without Administrator approval.
            </div>

            <div className="space-y-3 text-xs">
              <div>
                <label className="block text-stone-700 font-semibold mb-1">Final Compliance Determination *</label>
                <select
                  value={finalComplianceStatus}
                  onChange={(e) => setFinalComplianceStatus(e.target.value)}
                  className="w-full p-2 border border-stone-300 rounded bg-white font-bold"
                >
                  <option value="COMPLIANT">COMPLIANT (All mandatory statutory clauses satisfied)</option>
                  <option value="NON_COMPLIANT">NON_COMPLIANT (Statutory violation detected)</option>
                  <option value="CONDITIONAL_COMPLIANCE">CONDITIONAL_COMPLIANCE (Minor rectifyable defect)</option>
                  <option value="REJECTED">REJECTED (Inspection discarded / unreadable)</option>
                </select>
              </div>

              <div>
                <label className="block text-stone-700 font-semibold mb-1">Summary Inspection Notes</label>
                <textarea
                  rows={4}
                  value={summaryNotes}
                  onChange={(e) => setSummaryNotes(e.target.value)}
                  placeholder="Provide closing inspector observations, recommended enforcement action, or statutory notices..."
                  className="w-full p-2 border border-stone-300 rounded"
                />
              </div>
            </div>

            <div className="flex justify-end gap-2 pt-3 border-t">
              <button
                type="button"
                onClick={() => setShowFinalizeModal(false)}
                className="px-3 py-1.5 bg-stone-100 text-stone-700 rounded hover:bg-stone-200 text-xs"
              >
                Cancel
              </button>
              <button
                type="button"
                disabled={saving}
                onClick={handleFinalize}
                className="px-4 py-1.5 bg-emerald-900 text-white font-bold rounded hover:bg-emerald-800 text-xs"
              >
                {saving ? 'Finalizing…' : 'Confirm & Finalize'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal: Admin Reopen */}
      {showReopenModal && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-lg max-w-md w-full p-6 shadow-2xl space-y-4">
            <div className="flex justify-between items-center border-b pb-3">
              <h3 className="text-sm font-bold text-stone-900">🔓 Reopen Finalized Review</h3>
              <button type="button" onClick={() => setShowReopenModal(false)} className="text-stone-400 hover:text-stone-600 font-bold">✕</button>
            </div>

            <div className="p-3 bg-rose-50 border border-rose-200 rounded text-xs text-rose-900">
              <strong>Admin Authority:</strong> Reopening a finalized inspection unlocks it for inspector modification and logs a high-severity event in the Chain of Custody Audit Trail.
            </div>

            <div className="space-y-3 text-xs">
              <div>
                <label className="block text-stone-700 font-semibold mb-1">Administrative Justification *</label>
                <textarea
                  required
                  rows={4}
                  value={reopenReason}
                  onChange={(e) => setReopenReason(e.target.value)}
                  placeholder="Detail the formal basis for reopening (e.g., Legal appeal filed, supplementary package photo provided)..."
                  className="w-full p-2 border border-stone-300 rounded"
                />
              </div>
            </div>

            <div className="flex justify-end gap-2 pt-3 border-t">
              <button
                type="button"
                onClick={() => setShowReopenModal(false)}
                className="px-3 py-1.5 bg-stone-100 text-stone-700 rounded hover:bg-stone-200 text-xs"
              >
                Cancel
              </button>
              <button
                type="button"
                disabled={saving}
                onClick={handleReopen}
                className="px-4 py-1.5 bg-amber-700 text-white font-bold rounded hover:bg-amber-800 text-xs"
              >
                {saving ? 'Reopening…' : 'Authorize Reopen'}
              </button>
            </div>
          </div>
        </div>
      )}
    </section>
  )
}

import { useEffect, useState } from 'react'
import { api } from '../api/client'
import RuleLensModal from './RuleLensModal'

const VERDICT_STYLES = {
  PASS: 'bg-emerald-100 text-emerald-900 border-emerald-300',
  FAIL: 'bg-rose-100 text-rose-900 border-rose-300',
  UNCERTAIN: 'bg-amber-100 text-amber-900 border-amber-300',
  NOT_APPLICABLE: 'bg-stone-100 text-stone-700 border-stone-300',
}

const SEVERITY_STYLES = {
  CRITICAL: 'bg-rose-100 text-rose-800 border-rose-200',
  HIGH: 'bg-orange-100 text-orange-800 border-orange-200',
  MEDIUM: 'bg-amber-100 text-amber-800 border-amber-200',
  LOW: 'bg-blue-100 text-blue-800 border-blue-200',
  INFO: 'bg-stone-100 text-stone-700 border-stone-200',
}

export default function RuleComplianceEvaluation({ inspection, user, refreshKey, onEvaluationComplete }) {
  const [summary, setSummary] = useState(null)
  const [results, setResults] = useState([])
  const [loading, setLoading] = useState(false)
  const [evaluating, setEvaluating] = useState(false)
  const [error, setError] = useState(null)
  const [allowPrototypes, setAllowPrototypes] = useState(true)

  // Explainability Modal
  const [selectedExplanation, setSelectedExplanation] = useState(null)
  const [loadingExplanation, setLoadingExplanation] = useState(false)

  const base = `/inspections/${inspection.id}`
  const canEvaluate = ['INSPECTOR'].includes(user?.role)

  const fetchEvaluation = async () => {
    setLoading(true)
    setError(null)
    try {
      const summaryRes = await api.get(`${base}/evaluation`)
      setSummary(summaryRes.data)
      const resultsRes = await api.get(`${base}/evaluation/results`)
      setResults(resultsRes.data)
    } catch {
      // Non-fatal if no evaluation run exists yet
      setSummary(null)
      setResults([])
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchEvaluation()
  }, [inspection.id, refreshKey])

  const handleEvaluate = async () => {
    setEvaluating(true)
    setError(null)
    try {
      const { data } = await api.post(`${base}/evaluate`, {
        allow_prototype_rules: allowPrototypes,
      })
      setSummary(data)
      const resultsRes = await api.get(`${base}/evaluation/results`)
      setResults(resultsRes.data)
      if (onEvaluationComplete) onEvaluationComplete()
    } catch (err) {
      setError(err.response?.data?.detail || 'Failed to execute rule evaluation.')
    } finally {
      setEvaluating(false)
    }
  }

  const handleOpenRuleLens = async (ruleKey) => {
    setLoadingExplanation(true)
    try {
      const { data } = await api.get(`${base}/rules/${ruleKey}/explanation`)
      setSelectedExplanation(data)
    } catch (err) {
      alert(err.response?.data?.detail || 'Unable to generate RuleLens explanation.')
    } finally {
      setLoadingExplanation(false)
    }
  }

  return (
    <section className="bg-white border border-stone-300 rounded-lg p-6 shadow-sm my-6 space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b pb-4">
        <div>
          <div className="flex items-center gap-2">
            <h2 className="text-base font-bold font-serif text-stone-900">
              Legal Metrology Statutory Rule Evaluation
            </h2>
            <span className="text-[10px] bg-emerald-100 text-emerald-900 border border-emerald-300 px-2 py-0.5 rounded font-bold">
              Phase 8 Engine
            </span>
          </div>
          <p className="text-xs text-stone-500 mt-1">
            Deterministic statutory verification against the Legal Metrology (Packaged Commodities) Rules, 2011.
          </p>
        </div>

        {/* Evaluate Action Button */}
        {canEvaluate && (
          <div className="flex flex-col sm:flex-row items-end sm:items-center gap-3">
            <label className="flex items-center gap-1.5 text-xs text-stone-700 cursor-pointer">
              <input
                type="checkbox"
                checked={allowPrototypes}
                onChange={(e) => setAllowPrototypes(e.target.checked)}
                className="rounded text-emerald-800"
              />
              <span>Allow Prototype Rules</span>
            </label>
            <button
              type="button"
              disabled={evaluating}
              onClick={handleEvaluate}
              className="w-auto px-4 py-2 bg-emerald-900 hover:bg-emerald-800 text-white rounded text-xs font-bold shadow flex items-center gap-1.5 transition-colors"
            >
              {evaluating ? 'Evaluating Rules…' : '⚡ Run Statutory Verification'}
            </button>
          </div>
        )}
      </div>

      {error && (
        <div className="p-3 bg-rose-50 border border-rose-200 text-rose-900 text-xs rounded">
          ⚠️ {error}
        </div>
      )}

      {/* Summary KPI Cards */}
      {summary ? (
        <div className="space-y-4">
          <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
            <div className="p-3 bg-stone-50 border border-stone-200 rounded-lg">
              <div className="text-[10px] uppercase font-bold text-stone-500">Overall Verdict</div>
              <div className="mt-1">
                <span
                  className={`text-xs px-2.5 py-1 rounded font-bold border inline-block ${
                    VERDICT_STYLES[summary.overall] || VERDICT_STYLES.NOT_APPLICABLE
                  }`}
                >
                  {summary.overall}
                </span>
              </div>
            </div>

            <div className="p-3 bg-emerald-50 border border-emerald-200 rounded-lg">
              <div className="text-[10px] uppercase font-bold text-emerald-700">Passed (Compliant)</div>
              <div className="text-xl font-bold font-mono text-emerald-900 mt-0.5">
                {summary.pass_count}
              </div>
            </div>

            <div className="p-3 bg-rose-50 border border-rose-200 rounded-lg">
              <div className="text-[10px] uppercase font-bold text-rose-700">Violations (Fail)</div>
              <div className="text-xl font-bold font-mono text-rose-900 mt-0.5">
                {summary.fail_count}
              </div>
            </div>

            <div className="p-3 bg-amber-50 border border-amber-200 rounded-lg">
              <div className="text-[10px] uppercase font-bold text-amber-700">Uncertain (Review)</div>
              <div className="text-xl font-bold font-mono text-amber-900 mt-0.5">
                {summary.uncertain_count}
              </div>
            </div>

            <div className="p-3 bg-stone-50 border border-stone-200 rounded-lg">
              <div className="text-[10px] uppercase font-bold text-stone-600">Not Applicable</div>
              <div className="text-xl font-bold font-mono text-stone-800 mt-0.5">
                {summary.not_applicable_count}
              </div>
            </div>
          </div>

          {/* Prototype disclaimer */}
          {summary.prototype && (
            <div className="p-3 bg-amber-50 border-l-4 border-amber-500 text-amber-900 text-xs rounded space-y-0.5">
              <div className="font-bold">⚠️ Research Prototype Rules Active</div>
              <p className="text-[11px] text-amber-800">
                Evaluation includes prototype statutory rules. Results provide preliminary automated analysis for judicial &amp; inspector audit review.
              </p>
            </div>
          )}

          {/* Execution metadata bar */}
          <div className="flex flex-wrap items-center justify-between text-[11px] text-stone-500 bg-stone-50 p-2.5 rounded border border-stone-200 font-mono">
            <span>Ruleset: <strong>{summary.ruleset_id} (v{summary.ruleset_version})</strong></span>
            <span>Engine: <strong>v{summary.engine_version}</strong></span>
            <span>Evaluated: {new Date(summary.completed_at).toLocaleString()}</span>
            <span>Snapshot SHA: {summary.snapshot_sha256?.slice(0, 10)}…</span>
          </div>

          {/* Rule Results List */}
          <div className="space-y-3 mt-4">
            <h3 className="text-xs font-bold text-stone-800 uppercase tracking-wider">
              Statutory Declarations Verification Matrix ({results.length})
            </h3>

            {results.map((r) => {
              const vStyle = VERDICT_STYLES[r.verdict] || VERDICT_STYLES.NOT_APPLICABLE
              const sStyle = SEVERITY_STYLES[r.severity] || SEVERITY_STYLES.INFO

              return (
                <div
                  key={r.id}
                  className="border border-stone-200 rounded-lg p-4 bg-stone-50 hover:bg-white hover:border-emerald-700 hover:shadow-sm transition-all space-y-2"
                >
                  <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className={`text-xs px-2.5 py-0.5 rounded font-bold border ${vStyle}`}>
                        {r.verdict}
                      </span>
                      <span className={`text-[10px] px-1.5 py-0.5 rounded font-bold border uppercase ${sStyle}`}>
                        {r.severity}
                      </span>
                      <h4 className="text-xs font-bold text-stone-900">{r.title}</h4>
                      <span className="text-[10px] font-mono text-stone-400">({r.rule_key})</span>
                    </div>

                    <button
                      type="button"
                      disabled={loadingExplanation}
                      onClick={() => handleOpenRuleLens(r.rule_key)}
                      className="w-auto px-3 py-1 text-xs bg-emerald-950 hover:bg-emerald-900 text-white rounded font-semibold flex items-center gap-1 shadow-sm transition-colors self-start sm:self-auto"
                    >
                      <span>🔍 RuleLens™ Explain</span>
                    </button>
                  </div>

                  <p className="text-xs text-stone-700 leading-relaxed">{r.explanation}</p>

                  <div className="flex flex-wrap items-center justify-between text-[11px] text-stone-500 pt-1 border-t border-stone-200 gap-2">
                    <span className="italic">{r.legal_reference}</span>
                    <div className="flex items-center gap-3 font-mono">
                      <span>Reason: <strong>{r.reason_code}</strong></span>
                      {r.evidence_confidence !== null && (
                        <span>Confidence: <strong>{(r.evidence_confidence * 100).toFixed(0)}%</strong></span>
                      )}
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      ) : (
        <div className="text-center py-8 text-xs text-stone-500 bg-stone-50 rounded border border-stone-200 space-y-2">
          <p>No rule evaluation has been executed for this inspection snapshot yet.</p>
          {canEvaluate && (
            <p className="text-stone-600">
              Ensure context has been resolved, then click <strong>"Run Statutory Verification"</strong> to evaluate all statutory rules.
            </p>
          )}
        </div>
      )}

      {/* RuleLens Explanation Modal */}
      {selectedExplanation && (
        <RuleLensModal
          explanation={selectedExplanation}
          onClose={() => setSelectedExplanation(null)}
        />
      )}
    </section>
  )
}

import { useEffect, useState } from 'react'
import { Link, useLocation, useNavigate, useParams } from 'react-router-dom'
import { api } from '../api/client'
import { useAuth } from '../auth/AuthContext'
import ContextApplicability from '../components/ContextApplicability'
import ExtractedDeclarations from '../components/ExtractedDeclarations'
import RuleComplianceEvaluation from '../components/RuleComplianceEvaluation'
import HumanReviewWorkspace from '../components/HumanReviewWorkspace'
import AuditTrailViewer from '../components/AuditTrailViewer'
import ReportExportPanel from '../components/ReportExportPanel'
import AuthorizedImage from '../components/AuthorizedImage'
import InspectionOCRSummarySection from '../components/InspectionOCRSummarySection'
import OCRBlockTable from '../components/OCRBlockTable'
import OCRBoundingBoxCanvas from '../components/OCRBoundingBoxCanvas'

const STATUS_BADGE_STYLES = {
  GOOD: 'bg-emerald-100 text-emerald-800 border-emerald-300',
  ACCEPTABLE: 'bg-teal-100 text-teal-800 border-teal-300',
  POOR: 'bg-amber-100 text-amber-800 border-amber-300',
  UNREADABLE: 'bg-rose-100 text-rose-800 border-rose-300',
  PROCESSING_FAILED: 'bg-red-100 text-red-800 border-red-300',
  PENDING: 'bg-stone-100 text-stone-600 border-stone-300',
}

const FLAG_LABELS = {
  BLURRY: 'Blurry / Low Focus',
  TOO_DARK: 'Underexposed / Too Dark',
  TOO_BRIGHT: 'Overexposed / Too Bright',
  LOW_CONTRAST: 'Low Contrast',
  LOW_RESOLUTION: 'Low Resolution (<600px)',
  POSSIBLE_GLARE: 'Glare / Specular Reflection',
  INVALID_IMAGE: 'Corrupted / Invalid File',
  PROCESSING_ERROR: 'Pipeline Error',
}

export default function InspectionDetail() {
  const { id } = useParams()
  const navigate = useNavigate()
  const location = useLocation()
  const { user } = useAuth()

  const [contextRevision, setContextRevision] = useState(0)
  const [inspection, setInspection] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  // OCR state
  const [ocrSummary, setOcrSummary] = useState(null)
  const [loadingSummary, setLoadingSummary] = useState(false)
  const [ocrRunsByImageId, setOcrRunsByImageId] = useState({})
  const [loadingImageOCR, setLoadingImageOCR] = useState(false)

  // Modal interaction
  const [selectedImage, setSelectedImage] = useState(null)
  const [activeViewMode, setActiveViewMode] = useState('ocr-boxes') // 'ocr-boxes', 'side-by-side', 'original', 'preprocessed'
  const [selectedBlockId, setSelectedBlockId] = useState(null)
  const [hoveredBlockId, setHoveredBlockId] = useState(null)
  const [showOverlays, setShowOverlays] = useState(true)
  const [showLabels, setShowLabels] = useState(true)

  // Actions
  const [submitting, setSubmitting] = useState(false)
  const [processingBatchQuality, setProcessingBatchQuality] = useState(false)
  const [processingBatchOCR, setProcessingBatchOCR] = useState(false)
  const [processingSingleQualityId, setProcessingSingleQualityId] = useState(null)
  const [processingSingleOCRId, setProcessingSingleOCRId] = useState(null)
  const [bannerMessage, setBannerMessage] = useState(location.state?.message || null)

  const fetchInspection = async () => {
    setLoading(true)
    setError(null)
    try {
      const { data } = await api.get(`/inspections/${id}`)
      setInspection(data)
    } catch (err) {
      setError(
        err.response?.status === 404
          ? 'Inspection not found or access restricted.'
          : 'Failed to load inspection details.'
      )
    } finally {
      setLoading(false)
    }
  }

  const fetchOCRSummary = async () => {
    setLoadingSummary(true)
    try {
      const { data } = await api.get(`/inspections/${id}/ocr/summary`)
      setOcrSummary(data)
    } catch {
      // Non-fatal if OCR has not been executed yet
    } finally {
      setLoadingSummary(false)
    }
  }

  const fetchImageOCR = async (imageId) => {
    setLoadingImageOCR(true)
    try {
      const { data } = await api.get(`/inspections/${id}/images/${imageId}/ocr`)
      setOcrRunsByImageId((prev) => ({ ...prev, [imageId]: data }))
    } catch {
      // No OCR run for image yet
      setOcrRunsByImageId((prev) => ({ ...prev, [imageId]: null }))
    } finally {
      setLoadingImageOCR(false)
    }
  }

  useEffect(() => {
    fetchInspection()
    fetchOCRSummary()
  }, [id])

  useEffect(() => {
    if (selectedImage) {
      fetchImageOCR(selectedImage.id)
    }
  }, [selectedImage?.id])

  const handleSubmit = async () => {
    if (!inspection) return
    setSubmitting(true)
    try {
      const { data } = await api.post(`/inspections/${inspection.id}/submit`)
      setInspection(data)
      setBannerMessage('Inspection submitted successfully! It is now locked and ready for regulatory analysis.')
    } catch (err) {
      setError(err.response?.data?.detail || 'Failed to submit inspection.')
    } finally {
      setSubmitting(false)
    }
  }

  const handleProcessSingleQuality = async (imageId, force = false) => {
    setProcessingSingleQualityId(imageId)
    try {
      const { data } = await api.post(
        `/inspections/${id}/images/${imageId}/process${force ? '?force=true' : ''}`
      )
      setInspection((prev) => {
        if (!prev) return prev
        const updatedImages = prev.images.map((img) => {
          if (img.id === imageId) {
            return {
              ...img,
              quality_status: data.quality_status,
              width: data.width,
              height: data.height,
              processing_result: data,
            }
          }
          return img
        })
        return { ...prev, images: updatedImages }
      })

      if (selectedImage && selectedImage.id === imageId) {
        setSelectedImage((prev) => ({
          ...prev,
          quality_status: data.quality_status,
          width: data.width,
          height: data.height,
          processing_result: data,
        }))
      }
    } catch (err) {
      alert(err.response?.data?.detail || 'Failed to assess image quality.')
    } finally {
      setProcessingSingleQualityId(null)
    }
  }

  const handleBatchProcessQuality = async (force = false) => {
    setProcessingBatchQuality(true)
    try {
      await api.post(`/inspections/${id}/process-images${force ? '?force=true' : ''}`)
      const { data } = await api.get(`/inspections/${id}`)
      setInspection(data)
      setBannerMessage('Image quality assessment and OpenCV preprocessing completed for all evidence images.')
    } catch (err) {
      alert(err.response?.data?.detail || 'Failed to batch process images.')
    } finally {
      setProcessingBatchQuality(false)
    }
  }

  const handleProcessSingleOCR = async (imageId, force = false) => {
    setProcessingSingleOCRId(imageId)
    try {
      const { data } = await api.post(
        `/inspections/${id}/images/${imageId}/ocr${force ? '?force=true' : ''}`
      )
      setOcrRunsByImageId((prev) => ({ ...prev, [imageId]: data }))
      fetchOCRSummary()
    } catch (err) {
      alert(err.response?.data?.detail || 'Failed to execute OCR on evidence image.')
    } finally {
      setProcessingSingleOCRId(null)
    }
  }

  const handleBatchProcessOCR = async (force = false) => {
    setProcessingBatchOCR(true)
    try {
      await api.post(`/inspections/${id}/ocr${force ? '?force=true' : ''}`)
      await fetchOCRSummary()
      if (selectedImage) {
        await fetchImageOCR(selectedImage.id)
      }
      setBannerMessage('OCR text recognition completed across all package panels.')
    } catch (err) {
      alert(err.response?.data?.detail || 'Failed to execute batch OCR.')
    } finally {
      setProcessingBatchOCR(false)
    }
  }

  const handleOpenImageById = (imageId) => {
    const targetImg = inspection?.images.find((img) => img.id === imageId)
    if (targetImg) {
      setSelectedImage(targetImg)
      setActiveViewMode('ocr-boxes')
    }
  }

  const isEditable =
    inspection &&
    ['DRAFT', 'EVIDENCE_UPLOADED'].includes(inspection.status) &&
    ['INSPECTOR'].includes(user?.role)

  const canProcess =
    inspection &&
    ['INSPECTOR'].includes(user?.role)

  if (loading) {
    return (
      <main className="max-w-6xl mx-auto py-12 px-4 text-center text-xs text-stone-500">
        Loading inspection details…
      </main>
    )
  }

  if (error || !inspection) {
    return (
      <main className="max-w-4xl mx-auto py-12 px-4">
        <div className="bg-white border border-stone-300 rounded-lg p-8 text-center">
          <div className="text-3xl mb-2">⚠️</div>
          <h2 className="text-lg font-serif text-stone-900 font-bold mb-2">Unable to Open Inspection</h2>
          <p className="text-xs text-stone-600 mb-6">{error || 'Record could not be retrieved.'}</p>
          <Link to="/inspections" className="px-4 py-2 bg-stone-800 text-white rounded text-xs">
            ← Return to Inspections
          </Link>
        </div>
      </main>
    )
  }

  const activeImageOCR = selectedImage ? ocrRunsByImageId[selectedImage.id] : null
  const currentImageBlocks = activeImageOCR?.blocks || []

  return (
    <main className="max-w-6xl mx-auto py-8 px-4 sm:px-6">
      {/* Top Banner Notice */}
      {bannerMessage && (
        <div className="mb-6 p-4 bg-emerald-50 border-l-4 border-emerald-700 text-emerald-900 text-xs rounded flex justify-between items-center shadow-sm">
          <span>{bannerMessage}</span>
          <button
            type="button"
            onClick={() => setBannerMessage(null)}
            className="w-auto bg-transparent text-emerald-950 font-bold p-0"
          >
            ✕
          </button>
        </div>
      )}

      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-6 border-b border-stone-300">
        <div>
          <div className="flex items-center gap-2">
            <Link to="/inspections" className="text-xs text-emerald-900 hover:underline font-semibold">
              ← All Inspections
            </Link>
            <span className="text-stone-300">/</span>
            <span className="text-xs font-mono text-stone-500">{inspection.id.slice(0, 8)}…</span>
          </div>
          <div className="flex items-center gap-3 mt-2">
            <h1 className="text-3xl font-serif text-stone-900 font-bold">
              {inspection.inspection_code}
            </h1>
            <span
              className={`text-xs px-2.5 py-1 rounded font-semibold border ${
                inspection.status === 'READY_FOR_ANALYSIS'
                  ? 'bg-emerald-100 text-emerald-800 border-emerald-300'
                  : inspection.status === 'EVIDENCE_UPLOADED'
                  ? 'bg-blue-100 text-blue-800 border-blue-200'
                  : 'bg-stone-100 text-stone-700 border-stone-300'
              }`}
            >
              {inspection.status}
            </span>
          </div>
          <p className="text-xs text-stone-500 mt-1">
            Created by <strong>{inspection.created_by_name || 'Inspector'}</strong> on{' '}
            {new Date(inspection.created_at).toLocaleString()}
          </p>
        </div>

        {/* Action Controls */}
        <div className="flex items-center gap-2 flex-wrap">
          {canProcess && inspection.images_count > 0 && (
            <>
              <button
                type="button"
                disabled={processingBatchOCR}
                onClick={() => handleBatchProcessOCR(false)}
                className="w-auto px-4 py-2 text-xs bg-emerald-900 hover:bg-emerald-800 text-white font-semibold rounded shadow flex items-center gap-1.5 transition-colors"
              >
                {processingBatchOCR ? 'Extracting Text…' : '🔍 Extract Text (Batch OCR)'}
              </button>
              <button
                type="button"
                disabled={processingBatchQuality}
                onClick={() => handleBatchProcessQuality(false)}
                className="w-auto px-3 py-2 text-xs bg-stone-800 hover:bg-stone-900 text-white font-semibold rounded shadow flex items-center gap-1.5 transition-colors"
              >
                {processingBatchQuality ? 'Analyzing Quality…' : '⚡ Assess Quality'}
              </button>
            </>
          )}
          {isEditable && inspection.images_count > 0 && (
            <button
              type="button"
              disabled={submitting}
              onClick={handleSubmit}
              className="w-auto px-4 py-2 text-xs bg-emerald-950 hover:bg-emerald-900 text-white font-bold rounded shadow flex items-center gap-1.5 transition-colors"
            >
              {submitting ? 'Submitting…' : '✓ Submit for Analysis'}
            </button>
          )}
          {isEditable && (
            <button
              type="button"
              onClick={() => navigate('/inspections/new')}
              className="w-auto px-3.5 py-2 text-xs bg-stone-700 hover:bg-stone-800 text-white rounded font-medium"
            >
              + Add Evidence
            </button>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 my-8">
        {/* Left 2 Cols: Product & Photographic Evidence */}
        <div className="lg:col-span-2 space-y-6">
          {/* Product Specifications Card */}
          <section className="bg-white border border-stone-300 rounded-lg p-6 shadow-sm">
            <h2 className="text-sm font-semibold text-stone-900 uppercase tracking-wider mb-4 border-b pb-2">
              Product & Declaration Context
            </h2>
            <dl className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-3 text-xs">
              <div>
                <dt className="text-stone-500 font-medium">Product Name</dt>
                <dd className="font-semibold text-stone-900 mt-0.5 text-sm">{inspection.product_name || '—'}</dd>
              </div>
              <div>
                <dt className="text-stone-500 font-medium">Brand Name</dt>
                <dd className="font-semibold text-stone-900 mt-0.5 text-sm">{inspection.brand_name || '—'}</dd>
              </div>
              <div>
                <dt className="text-stone-500 font-medium">Product Category</dt>
                <dd className="text-stone-800 mt-0.5">{inspection.category || '—'}</dd>
              </div>
              <div>
                <dt className="text-stone-500 font-medium">Package Type</dt>
                <dd className="text-stone-800 mt-0.5">{inspection.package_type || '—'}</dd>
              </div>
              <div>
                <dt className="text-stone-500 font-medium">Import Status</dt>
                <dd className="text-stone-800 mt-0.5 font-mono">{inspection.import_status}</dd>
              </div>
              <div>
                <dt className="text-stone-500 font-medium">Barcode / GTIN</dt>
                <dd className="font-mono text-stone-800 mt-0.5">{inspection.barcode || '—'}</dd>
              </div>
              <div>
                <dt className="text-stone-500 font-medium">Manufacturer</dt>
                <dd className="text-stone-800 mt-0.5">{inspection.manufacturer_name || '—'}</dd>
              </div>
              <div>
                <dt className="text-stone-500 font-medium">Packer</dt>
                <dd className="text-stone-800 mt-0.5">{inspection.packer_name || '—'}</dd>
              </div>
              <div className="sm:col-span-2">
                <dt className="text-stone-500 font-medium">Importer</dt>
                <dd className="text-stone-800 mt-0.5">{inspection.importer_name || '—'}</dd>
              </div>
              {inspection.notes && (
                <div className="sm:col-span-2 pt-2 border-t border-stone-200">
                  <dt className="text-stone-500 font-medium">Field Notes</dt>
                  <dd className="text-stone-800 mt-0.5 italic">{inspection.notes}</dd>
                </div>
              )}
            </dl>
          </section>

          {/* Evidence Gallery Card */}
          <section className="bg-white border border-stone-300 rounded-lg p-6 shadow-sm">
            <div className="flex items-center justify-between mb-4 border-b pb-2">
              <div>
                <h2 className="text-sm font-semibold text-stone-900 uppercase tracking-wider">
                  Photographic Evidence & Quality Status ({inspection.images_count})
                </h2>
                <p className="text-[11px] text-stone-500 mt-0.5">
